/**
 * DELETE /api/v3/tags/unused — delete all tags of a workspace that are not applied to any response.
 *
 * Session-only, matching the other tag endpoints.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { successResponse } from "@/app/api/v3/lib/response";
import { prisma } from "@formbricks/database";
import { ZV3TagListQuery } from "../lib/schemas";

export const DELETE = withV3ApiWrapper({
  auth: "session",
  schemas: { query: ZV3TagListQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    const { workspaceId } = parsedInput.query;

    // Find tags that have no TagsOnResponses entries and delete them.
    const result = await prisma.tag.deleteMany({
      where: {
        workspaceId,
        responses: {
          none: {},
        },
      },
    });

    return successResponse({ deletedCount: result.count }, { requestId });
  },
});

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { deleteUnusedTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/** Delete all unused tags for a workspace, then invalidate the list. */
export const useDeleteUnusedTags = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (variables: { workspaceId: string }) => deleteUnusedTags(variables),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

"use client";

import { useState } from "react";
import { toast } from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { getV3ApiErrorMessage } from "@/modules/api/lib/v3-client";
import { Button } from "@/modules/ui/components/button";
import { DeleteDialog } from "@/modules/ui/components/delete-dialog";
import { useDeleteUnusedTags } from "../hooks/use-delete-unused-tags";

interface DeleteUnusedTagsButtonProps {
  workspaceId: string;
}

export const DeleteUnusedTagsButton = ({ workspaceId }: Readonly<DeleteUnusedTagsButtonProps>) => {
  const { t } = useTranslation();
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const deleteUnusedTags = useDeleteUnusedTags(workspaceId);

  const handleDeleteUnusedTags = async () => {
    try {
      const result = await deleteUnusedTags.mutateAsync({ workspaceId });
      toast.success(t("workspace.tags.delete_unused_tags_success", { count: result.deletedCount }));
      setOpenDeleteDialog(false);
    } catch (error) {
      toast.error(getV3ApiErrorMessage(error, t("common.something_went_wrong_please_try_again")));
    }
  };

  return (
    <>
      <Button variant="destructive" size="sm" onClick={() => setOpenDeleteDialog(true)}>
        {t("workspace.tags.delete_unused_tags")}
      </Button>
      <DeleteDialog
        open={openDeleteDialog}
        setOpen={setOpenDeleteDialog}
        deleteWhat={t("workspace.tags.delete_unused_tags")}
        text={t("workspace.tags.delete_unused_tags_confirmation")}
        onDelete={handleDeleteUnusedTags}
        isDeleting={deleteUnusedTags.isPending}
        buttonLabel={t("workspace.tags.delete_unused_tags")}
      />
    </>
  );
};

